const TOUR_ROTATION_MS = 5000;

function CinematicHero() {
  const [slide, setSlide] = useState(0);
  const [tourSlide, setTourSlide] = useState(0);
  const [tourCycle, setTourCycle] = useState(0);
  const [broken, setBroken] = useState([]);

  function findNext(current, direction, excluded, length) {
    for (let i = 1; i <= length; i += 1) {
      const next = (current + direction * i + length * 2) % length;
      if (!excluded.includes(next)) return next;
    }
    return current;
  }

  useEffect(() => {
    const timer = window.setInterval(() => {
      setSlide((current) => findNext(current, 1, broken, HERO_IMAGES.length));
    }, 3000);
    return () => window.clearInterval(timer);
  }, [broken]);

  // Automatic tour rotation: 1 → 2 → 3 → 4 → 5 → 1.
  // The main tattoo slideshow above keeps its original 3-second timing.
  useEffect(() => {
    const timer = window.setInterval(() => {
      setTourSlide((current) => (current + 1) % TOUR_STOPS.length);
    }, TOUR_ROTATION_MS);
    return () => window.clearInterval(timer);
  }, [tourCycle]);

  const activeTour = TOUR_STOPS[tourSlide];

  function nextTour() {
    setTourSlide((current) => (current + 1) % TOUR_STOPS.length);
    setTourCycle((count) => count + 1);
  }

  const next = (direction) =>
    setSlide((current) =>
      findNext(current, direction, broken, HERO_IMAGES.length),
    );

  const failHero = (index) => {
    setBroken((prev) => (prev.includes(index) ? prev : [...prev, index]));
    setSlide((prev) =>
      prev === index
        ? findNext(prev, 1, [...broken, index], HERO_IMAGES.length)
        : prev,
    );
  };

  return (
    <section className="ic26" aria-label="INKCONVENTION five-city tour 2026">
      <span className="ic26__verticalBrand" aria-hidden="true">
        INKCONVENTION
      </span>

      {/* Right-hand diagonal cinematic photo */}
      <div
        className="ic26__photo"
        role="region"
        aria-roledescription="carousel"
        aria-label="INKCONVENTION photographs"
      >
        {HERO_IMAGES.map((image, index) => (
          <img
            key={index}
            src={image.src}
            alt={index === slide ? image.alt : ""}
            aria-hidden={index !== slide}
            className={`ic26__heroImg ${index === slide ? "is-active" : ""}`}
            loading={index === 0 ? "eager" : "lazy"}
            onError={() => failHero(index)}
          />
        ))}
        <div className="ic26__photoShade" />
        <div className="ic26__more" aria-hidden="true">
          <span>MORE</span>
          <span>THAN</span>
          <span>INK.</span>
        </div>
        <span className="ic26__photoEdge" aria-hidden="true">
          TATTOO / ART / CULTURE / MUSIC
        </span>
        <div className="ic26__carousel">
          <span>
            {String(slide + 1).padStart(2, "0")} <i>/</i>{" "}
            {String(HERO_IMAGES.length).padStart(2, "0")}
          </span>
          <div className="ic26__carouselButtons">
            <button
              type="button"
              onClick={() => next(-1)}
              aria-label="Previous photograph"
            >
              <ArrowRight size={19} style={{ transform: "rotate(180deg)" }} />
            </button>
            <button
              type="button"
              onClick={() => next(1)}
              aria-label="Next photograph"
            >
              <ArrowRight size={19} />
            </button>
          </div>
        </div>
        <div className="ic26__filmstrip">
          <div className="ic26__thumbs">
            {HERO_IMAGES.map((image, index) => (
              <button
                type="button"
                key={index}
                disabled={broken.includes(index)}
                className={index === slide ? "is-active" : ""}
                onClick={() => setSlide(index)}
                aria-label={`Show photograph ${index + 1}`}
              >
                <img src={image.src} alt="" />
              </button>
            ))}
          </div>
          <strong>
            INKCONVENTION
            <br />
            2026
          </strong>
        </div>
      </div>

      {/* Large editorial heading and tour stop details */}
      <div className="ic26__content">
        <p className="ic26__eyebrow">
          <span>REAL ART</span>
          <b>/</b>
          <span>REAL ARTISTS</span>
          <b>/</b>
          <span>ONE COMMUNITY</span>
        </p>
        <div className="ic26__titleArea">
          <h1 className="ic26__title">
            <span className="ic26__titleInk">INK</span>
            <span
              className="ic26__titleConvention"
              style={{ "--ic26-title-photo": `url("${eventThree}")` }}
            >
              CONVENTION
            </span>
          </h1>
          <span className="ic26__year">
            2026 <i />
          </span>
          <button
            className="ic26__scroll"
            type="button"
            onClick={() =>
              document
                .querySelector(".inkEditorialVision")
                ?.scrollIntoView({ behavior: "smooth" })
            }
            aria-label="Scroll to explore"
          >
            <svg
              className="ic26__scrollLabel"
              viewBox="0 0 120 120"
              aria-hidden="true"
            >
              <defs>
                <path
                  id="ic26-scroll-circle"
                  d="M 60,60 m -48,0 a 48,48 0 1,1 96,0 a 48,48 0 1,1 -96,0"
                />
              </defs>
              <text>
                <textPath href="#ic26-scroll-circle">
                  SCROLL TO EXPLORE • SCROLL TO EXPLORE •{" "}
                </textPath>
              </text>
            </svg>
            <span className="ic26__scrollCore">
              <ArrowDown size={25} />
            </span>
          </button>
        </div>
        <p className="ic26__categories">
          <span>TATTOO</span>
          <b>/</b>
          <span>ART</span>
          <b>/</b>
          <span>CULTURE</span>
          <b>/</b>
          <span>MUSIC</span>
        </p>

        {/* Five tour locations automatically rotate every five seconds. */}
        <div
          className="ic26__event"
          key={activeTour.id}
          aria-label={`Tour stop ${tourSlide + 1} of ${TOUR_STOPS.length}: ${activeTour.city}`}
        >
          <Link
            to="/upcoming"
            className="ic26__lucknowPhoto"
            aria-label={`View upcoming event information for ${activeTour.city}`}
          >
            <img
              src={activeTour.photo}
              alt={`Venue reference photograph for ${activeTour.city}`}
              className="is-active"
              loading="eager"
            />
            <span className="ic26__photoCity">{activeTour.city}</span>
          </Link>
          <div className="ic26__eventDetails">
            <div className="ic26__eventMeta">
              <span className="ic26__nextStop">
                {activeTour.venueProvided ? "NEXT STOP" : "VENUE OPTION"}
              </span>
              <span className="ic26__eventCounter">
                {String(tourSlide + 1).padStart(2, "0")} / 05
              </span>
            </div>
            <h2>{activeTour.city}</h2>
            <p>
              <CalendarDays size={17} />
              <span>{activeTour.date}</span>
            </p>
            <p>
              <Clock3 size={17} />
              <span>{activeTour.time}</span>
            </p>
            <p>
              <MapPin size={17} />
              <span>
                <strong>{activeTour.venue}</strong>
                <br />
                {activeTour.address}
              </span>
            </p>
          </div>
          {/* Advance immediately; the 5-second auto-rotation continues. */}
          <button
            className="ic26__eventGo"
            type="button"
            onClick={nextTour}
            aria-label="Show next tour city"
          >
            <ArrowRight size={21} />
          </button>
          <span className="ic26__tourProgress" aria-hidden="true" />
        </div>
      </div>

      {/* The same four original links, now in the compact editorial button row */}
      <nav className="ic26__actions" aria-label="Quick actions">
        <Link to="/artists" className="ic26__action ic26__action--black">
          FIND YOUR ARTISTS <ArrowRight size={16} />
        </Link>

        <Link to="/entry" className="ic26__action">
          GET ENTRY PASS <ArrowRight size={16} />
        </Link>
        <Link to="/Enter" className="ic26__action">
          JOIN DIRECTORY FREE <ArrowRight size={16} />
        </Link>
      </nav>
    </section>
  );
}

